import * as OurXmlization from "../src/xmlization";

test("xmlization path renders as a relative XPath", () => {
  const path = new OurXmlization.Path();

  path.prepend(new OurXmlization.IndexSegment(3));
  path.prepend(new OurXmlization.ElementSegment("something"));

  expect(path.toString()).toStrictEqual("something/*[4]");
});

test("xmlization key segment renders as a predicate on the name", () => {
  const path = new OurXmlization.Path();

  path.prepend(new OurXmlization.ElementSegment("value"));
  path.prepend(new OurXmlization.KeySegment("a \"tricky\" <key>"));
  path.prepend(new OurXmlization.ElementSegment("struct"));

  expect(path.toString()).toStrictEqual(
    "struct/member[name=\"a &quot;tricky&quot; &lt;key&gt;\"]/value"
  );
});

test("xmlization errors default to empty path", () => {
  const deserializationError = new OurXmlization.DeserializationError("broken XML");
  expect(deserializationError.message).toStrictEqual("broken XML");
  expect(deserializationError.path.toString()).toStrictEqual("");

  const serializationError = new OurXmlization.SerializationError("broken object graph");
  expect(serializationError.message).toStrictEqual("broken object graph");
  expect(serializationError.path).toStrictEqual("");
});

test("xmlization serialization path renders as an access expression", () => {
  const error = new OurXmlization.SerializationError("broken object graph");

  error.prependKey("a b");
  error.prependIndex(3);
  error.prependProperty("something");

  expect(error.path).toStrictEqual('.something[3]["a b"]');
});

test("xmlization fails on malformed XML", () => {
  const malformedXml = "<something><notClosed>";
  const instanceOrError = OurXmlization.fromXmlString(malformedXml);
  expect(instanceOrError.error).not.toBeNull();
});

test("xmlization fails on empty XML", () => {
  const instanceOrError = OurXmlization.fromXmlString("");
  expect(instanceOrError.error).not.toBeNull();
});

test("xmlization fails on non-XML text", () => {
  const instanceOrError = OurXmlization.fromXmlString("Definitely not XML");
  expect(instanceOrError.error).not.toBeNull();
});

